import {simulate} from './model.js';
import {physicsDuration} from './physics.js';
export function duration(e,p){if(e.subject==='Physics')return physicsDuration(e.id,p);if(e.id==='electrolysis')return p.duration;if(e.id==='heating'||e.id==='diffusion')return 120;return 20;}
export function sampleSeries(e,params,axis='time',steps=80,maxTime){const control=e.controls.find(c=>c.id===axis);if(axis!=='time'&&(!control||control.options))throw new Error('Invalid sweep axis');const end=maxTime??duration(e,params);return Array.from({length:steps+1},(_,i)=>{let fraction=i/steps,x=axis==='time'?fraction*end:control.min+fraction*(control.max-control.min),p={...params};if(control)p[axis]=x;let q=axis==='time'?Math.min(1,x/duration(e,params)):1;let r=simulate(e.id,p,q);return {x,a:r.a,b:r.b};});}
export function csvFor(e,params,axis='time',baseline=null){let maxTime=baseline&&axis==='time'?Math.max(duration(e,params),duration(e,baseline)):undefined;let values=sampleSeries(e,params,axis,100,maxTime),compare=baseline?sampleSeries(e,baseline,axis,100,maxTime):null;const quote=s=>'"'+String(s).replaceAll('"','""')+'"';const name=axis==='time'?'Time (s)':e.controls.find(c=>c.id===axis).label;let rows=[[name,`${e.metricA} (${e.unitA})`,`${e.metricB} (${e.unitB})`,...(baseline?[`Baseline ${e.metricA}`,`Baseline ${e.metricB}`]:[])].map(quote).join(',')];for(let [i,row]of values.entries())rows.push([row.x,row.a,row.b,...(compare?[compare[i].a,compare[i].b]:[])].map(v=>v===null?'':Number(v).toPrecision(8)).join(','));return rows.join('\n');}
export function plotSvg(e,params,{axis='time',metric='a',baseline=null,progress=1}={}){let maxTime=baseline&&axis==='time'?Math.max(duration(e,params),duration(e,baseline)):undefined;let a=sampleSeries(e,params,axis,100,maxTime),b=baseline?sampleSeries(e,baseline,axis,100,maxTime):[];let values=[...a,...b].map(v=>v[metric]).filter(Number.isFinite),lo=Math.min(0,...values),hi=Math.max(0,...values);if(hi===lo)hi=lo+1;let pad=(hi-lo)*.1;lo-=pad;hi+=pad;const xmin=a[0].x,xmax=a.at(-1).x;let px=x=>52+(x-xmin)/(xmax-xmin||1)*540,py=y=>214-(y-lo)/(hi-lo)*176;const path=(rows,clip=false)=>{let open=false;return rows.map((v,i)=>{if(v[metric]===null||(clip&&axis==='time'&&v.x>duration(e,params)*progress)){open=false;return '';}let cmd=open?'L':'M';open=true;return `${cmd}${px(v.x).toFixed(2)},${py(v[metric]).toFixed(2)}`;}).join(' ');};const format=x=>Math.abs(x)>=100?x.toFixed(0):Math.abs(x)>=1?x.toFixed(1):x.toFixed(2);let grid='';for(let i=0;i<5;i++){let value=lo+(hi-lo)*i/4,y=py(value);grid+=`<path d="M52 ${y}H592" stroke="#dce3de"/><text x="44" y="${y+3}" text-anchor="end">${format(value)}</text>`;}for(let i=0;i<5;i++){let value=xmin+(xmax-xmin)*i/4;grid+=`<text x="${px(value)}" y="234" text-anchor="middle">${format(value)}</text>`;}let c=e.controls.find(c=>c.id===axis),xlabel=axis==='time'?'Simulated time (s)':`${c.label} ${c.unit?'('+c.unit+')':''}`,ylabel=metric==='a'?`${e.metricA} (${e.unitA})`:`${e.metricB} (${e.unitB})`;return `<svg viewBox="0 0 640 275" role="img" aria-label="${ylabel} versus ${xlabel}" class="analysis-chart"><g font-family="sans-serif" font-size="10" fill="#73877e">${grid}<text x="52" y="18" font-size="12" fill="#284940">${ylabel}</text><text x="322" y="260" text-anchor="middle">${xlabel}</text></g>${b.length?`<path d="${path(b)}" fill="none" stroke="#c28c50" stroke-width="2" stroke-dasharray="6 4"/>`:''}<path d="${path(a,true)}" fill="none" stroke="#338d85" stroke-width="2.4"/><path d="M52 38V214H592" stroke="#9aada3" fill="none"/></svg>`;}
