export function physicsDuration(id,p){if(id==='projectile')return 2*p.speed*Math.sin(p.angle*Math.PI/180)/p.gravity;if(id==='collision')return 2;if(id==='wave')return 4;return 12;}
export function getProjectileBounces(p, e = 0.58, kx = 0.82) {
  const r = Math.PI / 180;
  const vx0 = p.speed * Math.cos(p.angle * r);
  const vy0 = p.speed * Math.sin(p.angle * r);
  const g = p.gravity;
  const t0 = (2 * vy0) / g;
  const r0 = vx0 * t0;
  const h0 = (vy0 * vy0) / (2 * g);

  const bounces = [{ tStart: 0, tEnd: t0, dt: t0, xStart: 0, xEnd: r0, vx: vx0, vy: vy0, hMax: h0 }];
  let curT = t0;
  let curX = r0;
  let curVy = vy0;
  let curVx = vx0;

  for (let i = 1; i <= 3; i++) {
    curVy *= e;
    curVx *= kx;
    const dt = (2 * curVy) / g;
    const dx = curVx * dt;
    const hMax = (curVy * curVy) / (2 * g);
    bounces.push({
      tStart: curT,
      tEnd: curT + dt,
      dt,
      xStart: curX,
      xEnd: curX + dx,
      vx: curVx,
      vy: curVy,
      hMax
    });
    curT += dt;
    curX += dx;
  }
  return { bounces, totalTime: curT, totalRange: curX, flight: t0, range: r0, maxHeight: h0 };
}
export function simulatePhysics(id,p,q){let t=Math.max(0,Math.min(1,q))*physicsDuration(id,p),g=9.8,r=Math.PI/180;
 if(id==='pendulum'){let omega=Math.sqrt(p.gravity/p.length),angle=p.angle*r*Math.cos(omega*t),velocity=-p.angle*r*omega*Math.sin(omega*t);return {a:angle/r,b:2*Math.PI/omega,angle,velocity,time:t,hint:`Gravity ${p.gravity} m/s² · Period ${(2*Math.PI/omega).toFixed(2)} s.`};}
 if(id==='spring'){let omega=Math.sqrt(p.stiffness/p.mass),x=p.amplitude*Math.cos(omega*t),velocity=-p.amplitude*omega*Math.sin(omega*t),ke=.5*p.mass*velocity**2;return {a:x,b:ke,x,velocity,totalEnergy:.5*p.stiffness*p.amplitude**2,time:t,hint:'Energy moves between the spring and the mass; total energy stays constant.'};}
 if(id==='projectile'){let vx=p.speed*Math.cos(p.angle*r),vy0=p.speed*Math.sin(p.angle*r),flight=2*vy0/p.gravity;const bounceInfo=getProjectileBounces(p);return {a:Math.max(0,vy0*t-.5*p.gravity*t*t),b:vx*t,vx,vy:vy0-p.gravity*t,flight,range:vx*flight,maxHeight:vy0*vy0/(2*p.gravity),time:t,bounces:bounceInfo.bounces,totalRange:bounceInfo.totalRange,totalTime:bounceInfo.totalTime,hint:`Flight time ${flight.toFixed(2)} s · Range ${(vx*flight).toFixed(2)} m. Gravity speed: ${p.gravity} m/s² with ground bounces.`};}
 if(id==='incline'){let acc=Math.max(0,g*(Math.sin(p.angle*r)-p.friction*Math.cos(p.angle*r))),end=acc>0?Math.sqrt(10/acc):Infinity;let distance,speedAtT;if(t<=end){distance=.5*acc*t*t;speedAtT=acc*t;}else{const dtAfter=t-end,vImpact=acc*end,eBumper=.45,vRebound=vImpact*eBumper,aUphill=g*(Math.sin(p.angle*r)+p.friction*Math.cos(p.angle*r)),tApex=aUphill>0?vRebound/aUphill:0;let reboundDist;if(dtAfter<tApex){reboundDist=vRebound*dtAfter-.5*aUphill*dtAfter*dtAfter;speedAtT=-(vRebound-aUphill*dtAfter);}else{const dtDown=dtAfter-tApex,peakDist=.5*vRebound*tApex;reboundDist=Math.max(0,peakDist-.5*acc*dtDown*dtDown);speedAtT=Math.min(vImpact*.3,acc*dtDown);}distance=Math.max(0,Math.min(5,5-reboundDist));}return {a:t>=end?Math.abs(speedAtT):acc*t,b:t>=end?0:p.mass*acc,distance,acc,time:t,hint:acc===0?'Static friction balances the downhill component of gravity.':t>=end?'The block struck the end stop and recoiled with bumper bounce.':'Net downhill gravity force accelerates the block.'};}
 if(id==='collision'){let u=2,v1=(p.mass1-p.elasticity*p.mass2)/(p.mass1+p.mass2)*u,v2=(1+p.elasticity)*p.mass1/(p.mass1+p.mass2)*u;let after=t>=1;return {a:after?v1:u,b:after?v2:0,x1:after?v1*(t-1):-2+u*t,x2:after?v2*(t-1):0,momentum:p.mass1*u,energyLoss:.5*p.mass1*u*u-(.5*p.mass1*v1*v1+.5*p.mass2*v2*v2),time:t,hint:after?`Momentum conserved: ${(p.mass1*u).toFixed(2)} kg·m/s. Kinetic energy loss: ${(.5*p.mass1*u*u-(.5*p.mass1*v1*v1+.5*p.mass2*v2*v2)).toFixed(2)} J.`:'Cart 1 approaches at 2 m/s. Cart 2 is stationary.'};}
 if(id==='circuit'){let resistance=p.parallel?1/(1/p.r1+1/p.r2):p.r1+p.r2,i=q>0?p.voltage/resistance:0;return {a:i,b:p.voltage*i,resistance,i1:p.parallel?(q>0?p.voltage/p.r1:0):i,i2:p.parallel?(q>0?p.voltage/p.r2:0):i,time:t,hint:`Equivalent resistance: ${resistance.toFixed(2)} Ω. ${p.parallel?'Both branches share the supply voltage.':'Both resistors carry the same current.'}`};}
 if(id==='refraction'){let sin=p.n1/p.n2*Math.sin(p.angle*r),tir=sin>1,theta=tir?null:Math.asin(sin)/r,critical=p.n1>p.n2?Math.asin(p.n2/p.n1)/r:null;return {a:theta,b:p.angle,tir,critical,time:t,hint:tir?`Total internal reflection. Critical angle: ${critical.toFixed(2)}°.`:critical?`Critical angle: ${critical.toFixed(2)}°. All angles are measured from the normal.`:'A higher refractive index bends the transmitted ray toward the normal.'};}
 if(id==='lens'){let u=p.focal*p.distance,v=p.focal*u/(u-p.focal),m=-v/u;return {a:v,b:m,u,v,m,height:p.height*m,time:t,hint:`Object at ${u.toFixed(2)} m. The real image is inverted and ${Math.abs(m).toFixed(2)}× the object size.`};}
 if(id==='wave'){let speed=Math.sqrt(p.tension/p.density),wavelength=speed/p.frequency;return {a:wavelength,b:speed,time:t,hint:'The highlighted bead oscillates vertically; the wave pattern travels along the string.'};}
 if(id==='buoyancy'){let fraction=p.immersion/100*q,volume=p.volume*1e-6,weight=p.density*g*volume,force=1000*g*volume*fraction;return {a:force,b:weight-force,fraction,weight,time:t,hint:weight-force<0?'A downward support force is needed. Released here, the object would rise.':'The support carries the weight not balanced by buoyancy.'};}
 throw new Error('Unknown physics experiment: '+id);
}
